note.ddx:
{
  "step1_summary": [
    "Chief complaint: Sudden onset of profuse watery diarrhoea for 3 days.",
    "Symptoms: • Frequency: almost every hour while awake • Consistency: very watery, no blood • Crampy mid-lower abdominal pain, colicky, ~6/10, precedes bowel actions • Associated: nausea and occasional vomiting (worse with milk), subjective fever/feeling hot, mild ↓ urine output • Able to take some solids but stools remain loose.",
    "Onset/duration: Started ~3 days ago (Mon/Tue); still ongoing.",
    "Aggravating factors: Milk induces vomiting; drinking seems to ‘go straight through’.",
    "Alleviating factors: None stated; takes paracetamol for fever/pain.",
    "Past medical history: Denies chronic illnesses; otherwise fit & well.",
    "Medications/allergies: No regular meds; intermittent paracetamol. No known drug allergies.",
    "Family history: Father with stage-III colon cancer; brother currently has similar 5-day diarrhoeal illness.",
    "Social history: 27-year-old male; lives with mother & sister; office worker; social smoker; alcohol socially/binge monthly; often buys takeaway food; no recent travel mentioned.",
    "Vitals/exam: Tele-visit—no objective vitals. Patient feels febrile but temperature not measured. No physical exam findings provided.",
    "Labs/imaging: None performed or reported."
  ],
  "step2_vindicate": {
    "V": [
      "Ischaemic colitis: Usually presents with sudden pain + bloody diarrhoea; less likely given age & absence of blood."
    ],
    "I": [
      "Acute viral gastroenteritis (e.g., norovirus/rotavirus): Very common, abrupt watery diarrhoea, vomiting, low-grade fever, person-to-person spread (brother affected).",
      "Acute bacterial food-borne gastroenteritis (Campylobacter, Salmonella, E. coli, Shigella): Similar presentation; often after contaminated food; may have fever and abdominal cramps.",
      "Giardiasis: Watery foul diarrhoea, nausea, lactose intolerance–like symptoms; possible if contaminated water/food."
    ],
    "N": [
      "Colorectal malignancy (early-onset): Family history; can cause change in bowel habit, but acute watery diarrhoea less typical.",
      "Neuroendocrine (carcinoid) tumour: Can produce secretory diarrhoea, flushing/‘hot’ feeling."
    ],
    "D": [
      "Primary lactose intolerance: Milk triggers vomiting/diarrhoea; usually chronic but can flare after infections.",
      "Other malabsorption (e.g., pancreatic insufficiency, coeliac) causing diarrhoea."
    ],
    "I2": [
      "Drug-induced diarrhoea (e.g., antibiotics, laxatives, metformin): Not on such agents."
    ],
    "C": [
      "Congenital enzyme defects (e.g., sucrase-isomaltase deficiency): Would be lifelong; not new."
    ],
    "A": [
      "Coeliac disease: Immune-mediated; chronic malabsorptive diarrhoea and weight loss."
    ],
    "T": [
      "Abdominal trauma with enteric leak: No history of injury."
    ],
    "E": [
      "Hyperthyroidism: Can produce frequent stools/diarrhoea and heat intolerance."
    ]
  },
  "step3_ranked_ddx": [
    {
      "diagnosis": "Acute viral gastroenteritis (likely norovirus)",
      "likelihood": "High",
      "explanation": "Most common cause of abrupt, profuse watery diarrhoea with mild fever; highly contagious—brother ill; typically self-limited in young adults."
    },
    {
      "diagnosis": "Acute bacterial gastroenteritis / food-borne infection",
      "likelihood": "Medium",
      "explanation": "Similar presentation with abdominal cramping and watery stools; possible if recent takeaway food; feverish sensation supports inflammatory pathogen."
    },
    {
      "diagnosis": "Secondary (transient) lactose intolerance after enteric infection",
      "likelihood": "Low-Medium",
      "explanation": "Milk ingestion precipitates vomiting; enteric infections can cause temporary lactase deficiency, worsening diarrhoea when dairy consumed."
    },
    {
      "diagnosis": "Inflammatory bowel disease (Crohn’s/Ulcerative colitis)",
      "likelihood": "Low",
      "explanation": "Can give diarrhoea and crampy pain in 20s age group; however usually more chronic, may have blood/mucus and extra-intestinal features."
    }
  ],
  "supporting_opposing_evidence": {
    "Acute viral gastroenteritis": {
      "supporting_evidence": [
        "Very acute onset (3 days)",
        "Profuse watery diarrhoea without blood",
        "Brother sick with similar illness—suggests infective spread",
        "Nausea/vomiting and subjective fever typical of viral GE",
        "No regular medications or comorbidities"
      ],
      "opposing_evidence": [
        "No objective fever recorded",
        "Frequency extremely high (hourly); could also fit severe bacterial infection"
      ]
    },
    "Acute bacterial gastroenteritis": {
      "supporting_evidence": [
        "Watery diarrhoea and abdominal cramps",
        "Subjective fever/‘burning up’",
        "Eats takeaway food frequently",
        "High stool frequency suggests possible secretory/invasive bacterial pathogen"
      ],
      "opposing_evidence": [
        "Absence of blood or mucus in stool (common with Campylobacter/Shigella)",
        "No reported recent travel or obvious food exposure",
        "Brother ill—still could be common food source but also fits viral spread"
      ]
    },
    "Transient lactose intolerance": {
      "supporting_evidence": [
        "Milk immediately provokes vomiting",
        "Watery diarrhoea can be worsened by dairy products",
        "Often occurs after mucosal injury from viral GE"
      ],
      "opposing_evidence": [
        "Symptoms not limited to dairy ingestion—diarrhoea ongoing even with other foods",
        "Very acute presentation rather than long-standing intolerance"
      ]
    },
    "Inflammatory bowel disease": {
      "supporting_evidence": [
        "Young adult age (27)",
        "Crampy abdominal pain with diarrhoea"
      ],
      "opposing_evidence": [
        "Acute onset rather than chronic relapsing course",
        "No blood, weight loss, or extra-intestinal symptoms",
        "Family history negative for IBD"
      ]
    }
  }
}
